'use strict';
const $=id=>document.getElementById(id),fmt=(v,d=3)=>Number(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels=Engine.refs.map((r,k)=>(k?' '+Engine.refs[k-1][0]+' < P ≤ ':'0 < P ≤ ')+r[0]+' MW');let rows=[],historical=[],ons=[],groups=[];
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500)}
function tab(name){document.querySelectorAll('main>section').forEach(e=>e.hidden=e.id!==name);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.tab===name))}
document.querySelectorAll('nav button').forEach(e=>e.onclick=()=>tab(e.dataset.tab));
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function persist(){try{localStorage.setItem('uhe-ref-v1',JSON.stringify({rows,pmo:$('pmo').value,study:$('study').value,groups,single:Object.fromEntries(['plant','teif','ip','year','power','unit'].map(id=>[id,$(id).value]))}));$('saved').textContent='Cenário salvo neste navegador.'}catch(e){$('saved').textContent='Não foi possível salvar no navegador. Exporte um backup.'}}
function calc(){try{const t=$('teif').value,i=$('ip').value,y=Number($('year').value),p=Number($('power').value);if(!Number.isInteger(y)||y<2000||y>2100||!Number.isFinite(p)||p<=0)throw Error('Informe ano entre 2000 e 2100 e potência positiva.');const d=Engine.availability(t,i),h=(Date.UTC(y+1,0,1)-Date.UTC(y,0,1))/3600000;$('disp').textContent=fmt(d)+'%';$('bar').style.width=d+'%';$('unavail').textContent=fmt(100-d)+'%';$('hours').textContent=fmt(h*(1-d/100),2)+' h';$('mw').textContent=fmt(p*d/100)+' MW';$('calcMsg').textContent=$('plant').value+' · '+y+' · '+fmt(h,0)+' h/ano';persist();return {usina:$('plant').value,ano:y,teif_pct:+t,ip_pct:+i,disponibilidade_pct:d,horas_ano:h,horas_equivalentes_indisponiveis:h*(1-d/100),potencia_mw:p,potencia_equivalente_mw:p*d/100,fonte:$('inputSource').textContent,status:'Simulação, sem homologação'}}catch(e){$('calcMsg').textContent=e.message;$('disp').textContent='—';['unavail','hours','mw'].forEach(id=>$(id).textContent='—');$('bar').style.width='0%';return null}}
['plant','teif','ip','year','power','unit'].forEach(id=>$(id).oninput=()=>{if(['teif','ip'].includes(id))$('inputSource').textContent='Taxas do cenário.';calc()});
$('loadref').onclick=()=>{try{let b=Engine.band(Number($('unit').value)),r=Engine.refs[b-1];$('teif').value=r[1];$('ip').value=r[2];$('inputSource').textContent='Portaria 42/2022 · '+labels[b-1]+' · referência consultada em 30/10/2026.';calc()}catch(e){toast(e.message)}};
$('exportSingle').onclick=()=>{const r=calc();if(r)download('memoria_disponibilidade.json',JSON.stringify(r,null,2));else toast('Corrija os valores antes de exportar.')};
function renderGroups(){$('groups').innerHTML=groups.map((g,k)=>`<div class="rowgroup"><span>${g.n} UGs × ${fmt(g.p)} MW · Faixa ${g.band}</span><span>TEIF ${fmt(g.teif)}% / IP ${fmt(g.ip)}%</span><button data-remove-group="${k}" aria-label="Remover conjunto ${k+1}">Remover</button></div>`).join('');const r=Engine.aggregate(groups,'weight');$('mixedOut').textContent=r?`Potência total: ${fmt(r.weight)} MW · TEIF: ${fmt(r.teif,6)}% · IP: ${fmt(r.ip,6)}% · D: ${fmt(r.disp,6)}%`:'Nenhum conjunto informado.';persist()}
$('groups').onclick=e=>{if(e.target.dataset.removeGroup!==undefined){groups.splice(+e.target.dataset.removeGroup,1);renderGroups()}};
$('addgroup').onclick=()=>{try{const n=Number($('gn').value),p=Number($('gp').value),b=Engine.band(p);if(!Number.isInteger(n)||n<1)throw Error('Quantidade de UGs deve ser um inteiro positivo.');groups.push({n,p,band:b,weight:n*p,teif:Engine.refs[b-1][1],ip:Engine.refs[b-1][2]});renderGroups()}catch(e){toast(e.message)}};
function cutoff(){const y=Number($('pmo').value);if(!Number.isInteger(y)||y<2000||y>2100)throw Error('Ano do PMO inválido');return `${y-6}-12-31`}
function reason(r){if(!r.include)return 'Excluída pelo usuário';if(!r.name.trim())return 'Nome ausente';if(!Number.isInteger(+r.band)||r.band<1||r.band>5)return 'Faixa inválida';if(!Number.isInteger(+r.n)||r.n<=0)return 'UGs inválidas';if(!r.same)return 'UGs em faixas distintas';if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||Number.isNaN(Date.parse(r.date))||new Date(r.date+'T00:00:00Z').toISOString().slice(0,10)!==r.date)return 'Motorização não validada';if(r.date>cutoff())return 'Motorização posterior ao corte';try{Engine.availability(r.teif,r.ip)}catch(e){return e.message}return ''}
function renderRows(){$('rows').innerHTML=rows.map((r,k)=>`<tr class="${reason(r)?'invalid':''}"><td><input aria-label="Incluir ${esc(r.name)}" type="checkbox" data-k="${k}" data-f="include" ${r.include?'checked':''}></td><td><input aria-label="Nome da usina" data-k="${k}" data-f="name" value="${esc(r.name)}"></td><td><select aria-label="Faixa de potência" data-k="${k}" data-f="band">${labels.map((x,i)=>`<option value="${i+1}" ${+r.band===i+1?'selected':''}>${i+1} · ${x}</option>`).join('')}</select></td><td><input aria-label="Número de UGs" type="number" min="1" step="1" value="${r.n}" data-k="${k}" data-f="n"></td><td><input aria-label="TEIF percentual" type="number" min="0" max="100" step="0.001" value="${r.teif}" data-k="${k}" data-f="teif"></td><td><input aria-label="IP percentual" type="number" min="0" max="100" step="0.001" value="${r.ip}" data-k="${k}" data-f="ip"></td><td><input aria-label="Data de motorização" type="date" value="${esc(r.date)}" data-k="${k}" data-f="date"></td><td><input aria-label="Mesma faixa de potência" type="checkbox" data-k="${k}" data-f="same" ${r.same?'checked':''}></td><td class="source" id="rs${k}">${esc(reason(r)||r.source||'Incluída')}</td><td><button data-delete="${k}" aria-label="Remover ${esc(r.name)}">×</button></td></tr>`).join('');aggregate()}
function aggregate(){try{const y=Number($('pmo').value),c=cutoff();$('window').textContent=`PMO maio/${y} → janela ${y-5}–${y-1} → motorização completa até ${c.split('-').reverse().join('/')}.`;let eligible=rows.filter(r=>!reason(r));$('aggregates').innerHTML=labels.map((label,k)=>{let a=Engine.aggregate(eligible.filter(r=>+r.band===k+1)),ref=Engine.refs[k],rd=Engine.availability(ref[1],ref[2]);return `<tr><td>${label}</td><td>${a?a.weight:0}</td><td>${a?fmt(a.teif,6)+'%':'—'}</td><td>${a?fmt(a.ip,6)+'%':'—'}</td><td>${a?fmt(a.disp,6)+'%':'—'}</td><td>${a?fmt(a.disp-rd,6)+' p.p.':'—'}</td></tr>`}).join('');const keys=rows.map(r=>r.name.trim().toUpperCase()),dup=keys.filter((n,i)=>keys.indexOf(n)!==i);$('audit').textContent=`${eligible.length} linhas incluídas / ${rows.length} informadas. ${rows.length-eligible.length} excluídas. `+(dup.length?'Nomes duplicados: '+[...new Set(dup)].join(', ')+'. Confira a contagem. ':'')+($('study').value.includes('Anexo I')?'Anexo I: faixa 1 com 56 UGs (Tabela 4: 58); faixas 2–5 coincidem a três casas. Ver auditoria na metodologia.':'Estimativa do conjunto informado.');rows.forEach((r,k)=>{let el=$('rs'+k);if(el){el.textContent=reason(r)||r.source||'Incluída';el.closest('tr').classList.toggle('invalid',!!reason(r))}});persist()}catch(e){$('audit').textContent=e.message;$('aggregates').innerHTML=''}}
$('rows').onchange=e=>{let el=e.target;if(el.dataset.k!==undefined){let f=el.dataset.f,v=el.type==='checkbox'?el.checked:el.value;if(['band','n','teif','ip'].includes(f))v=el.value===''?'':Number(el.value);rows[+el.dataset.k][f]=v;aggregate()}};
$('rows').onclick=e=>{if(e.target.dataset.delete!==undefined){rows.splice(+e.target.dataset.delete,1);renderRows()}};
function restoreHistoric(){rows=historical.map(r=>({...r,date:'2015-12-31',include:true,same:true,source:`Anexo I, p. ${r.page}; corte 2015 validado pelo relatório`}));$('pmo').value=2021;$('study').value='Reprodução literal do Anexo I · PMO maio/2021';renderRows()}
$('historic').onclick=()=>{if(confirm('Substituir o cenário pela reprodução do Anexo I? Exporte antes para conservar alterações.'))restoreHistoric()};
$('newcohort').onclick=()=>tab('ctg');
$('addrow').onclick=()=>{rows.push({name:'Nova usina',band:3,n:1,teif:0,ip:0,date:'',same:true,include:true,source:'Entrada manual; validar taxa quinquenal no PMO'});renderRows();$('rows').lastElementChild.scrollIntoView({block:'nearest'})};
$('pmo').onchange=()=>{aggregate()};$('study').oninput=persist;
const quote=s=>'"'+String(s??'').replace(/"/g,'""')+'"';function csv(rows){return rows.map(r=>r.map(quote).join(';')).join('\r\n')}
$('exportCohort').onclick=()=>download('cenario_referencia.csv','\uFEFF'+csv([['nome','faixa','ugs','teif_pct','ip_pct','motorizacao','mesma_faixa','incluir'],...rows.map(r=>[r.name,r.band,r.n,r.teif,r.ip,r.date,r.same?1:0,r.include?1:0])]),'text/csv;charset=utf-8');
$('backup').onclick=()=>download('estudo_referencia.json',JSON.stringify({version:1,study:$('study').value,pmo:$('pmo').value,rows,data_pesquisa:'2026-10-30',status:'Simulação, não homologada'},null,2));
function parseCSV(t){t=t.replace(/^\uFEFF/,'');let result=[],row=[],s='',q=false;for(let i=0;i<t.length;i++){let c=t[i];if(c==='"'){if(q&&t[i+1]==='"'){s+='"';i++}else q=!q}else if(c===';'&&!q){row.push(s);s=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&t[i+1]==='\n')i++;row.push(s);if(row.some(x=>x.trim()))result.push(row);row=[];s=''}else s+=c}if(q)throw Error('CSV com aspas não fechadas');row.push(s);if(row.some(x=>x.trim()))result.push(row);return result}
$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('Limite: 10 MB.');const text=await f.text();let incoming,pmo=$('pmo').value,study='Importado: '+f.name;if(f.name.endsWith('.json')){let v=JSON.parse(text);incoming=v.rows;pmo=v.pmo;study=v.study;if(!Number.isInteger(+pmo)||pmo<2000||pmo>2100||typeof study!=='string')throw Error('Metadados JSON inválidos.')}else{let all=parseCSV(text),h=all.shift();if(h.join(';')!=='nome;faixa;ugs;teif_pct;ip_pct;motorizacao;mesma_faixa;incluir')throw Error('Cabeçalho CSV diferente do modelo.');incoming=all.map((a,k)=>{if(a.length!==8)throw Error('Linha '+(k+2)+': esperadas 8 colunas.');if(!['0','1'].includes(a[6])||!['0','1'].includes(a[7]))throw Error('Linha '+(k+2)+': booleanos devem ser 0 ou 1.');return {name:a[0],band:+a[1],n:+a[2],teif:a[3]===''?'':Number(a[3].replace(',','.')),ip:a[4]===''?'':Number(a[4].replace(',','.')),date:a[5],same:a[6]==='1',include:a[7]==='1',source:'Importação CSV; fonte a validar'}})}if(!Array.isArray(incoming)||incoming.length>5000)throw Error('Lista inválida ou acima de 5.000 linhas.');incoming.forEach((r,k)=>{if(typeof r.name!=='string'||r.name.length>200||!Number.isInteger(+r.band)||r.band<1||r.band>5||!Number.isInteger(+r.n)||r.n<=0||typeof r.date!=='string'||typeof r.same!=='boolean'||typeof r.include!=='boolean')throw Error('Linha '+(k+1)+': cadastro inválido.');Engine.availability(r.teif,r.ip)});rows=incoming;$('pmo').value=pmo;$('study').value=study;renderRows();$('importMsg').textContent=incoming.length+' linhas importadas. Linhas sem motorização válida são excluídas do cálculo.';toast('Importação concluída.')}catch(err){$('importMsg').textContent='Importação recusada: '+err.message}finally{e.target.value=''}};
function renderOns(){let f=$('filter').value.toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');$('onsRows').innerHTML=ons.map((r,k)=>({...r,k})).filter(r=>r.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(f)).map(r=>`<tr><td>${esc(r.name)}</td><td>${fmt(r.TEIFa,6)}</td><td>${fmt(r.TEIP,6)}</td><td>${fmt(Engine.availability(r.TEIFa,r.TEIP),6)}</td><td><button data-ons="${r.k}">Simular</button></td></tr>`).join('')}
$('onsRows').onclick=e=>{if(e.target.dataset.ons!==undefined){const r=ons[+e.target.dataset.ons];$('plant').value=r.name;$('teif').value=r.TEIFa;$('ip').value=r.TEIP;$('inputSource').textContent='ONS · TEIFa/TEIP acumuladas · '+r.month+' · CEG '+r.ceg+'. Transferidas como cenário; não homologadas para 2027.';calc();tab('calc');window.scrollTo({top:260,behavior:'smooth'})}};$('filter').oninput=renderOns;
$('downloadOns').onclick=()=>download('ons_uhe_2026_09.csv','\uFEFF'+csv([['usina','ceg','mes','teifa_pct','teip_pct','disponibilidade_calculada_pct'],...ons.map(r=>[r.name,r.ceg,r.month,r.TEIFa,r.TEIP,Engine.availability(r.TEIFa,r.TEIP)])]),'text/csv;charset=utf-8');
$('official').innerHTML=labels.map((l,k)=>`<tr><td>${l}</td><td>${fmt(Engine.refs[k][1])}</td><td>${fmt(Engine.refs[k][2])}</td><td>${fmt(Engine.availability(Engine.refs[k][1],Engine.refs[k][2]))}</td></tr>`).join('');
(async()=>{try{[historical,ons]=await Promise.all(['historical.json','ons.json'].map(u=>fetch(u).then(r=>{if(!r.ok)throw Error('Não foi possível carregar '+u);return r.json()})));let saved;try{saved=JSON.parse(localStorage.getItem('uhe-ref-v1'))}catch(e){}if(saved&&Array.isArray(saved.rows)){rows=saved.rows;$('study').value=saved.study;$('pmo').value=saved.pmo;groups=saved.groups||[];Object.entries(saved.single||{}).forEach(([k,v])=>{if($(k))$(k).value=v});$('inputSource').textContent='Cenário recuperado deste navegador; confira as taxas e sua fonte.';renderRows()}else restoreHistoric();renderOns();renderGroups();calc()}catch(e){toast(e.message);$('audit').textContent=e.message;calc()}})();
